class Solution {
    public int findDuplicate(int[] nums) {
        // 1 step faster.
        int slow = nums[0];
        int fast = nums[slow];
        // loop to find out the intersection point.
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[nums[fast]];
        }

        // go back to the entrance of the cycle.
        fast = 0;
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[fast];
        }
        return slow;
    }
}
// Time Complexity: O(n)
